package com.smartsociety.platform.complaint;
import com.smartsociety.platform.auth.User; import com.smartsociety.platform.common.Enums.*; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="complaints",indexes={@Index(name="idx_complaint_resident",columnList="resident_id"),@Index(name="idx_complaint_status",columnList="current_status"),@Index(name="idx_complaint_due",columnList="due_at"),@Index(name="idx_complaint_created",columnList="created_at")}) public class Complaint { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="resident_id") User resident; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id") ComplaintCategory category; @Column(nullable=false,length=150) String title; @Column(nullable=false,length=5000) String description; @Enumerated(EnumType.STRING) @Column(nullable=false) Priority priority=Priority.MEDIUM; @Enumerated(EnumType.STRING) @Column(name="current_status",nullable=false) ComplaintStatus currentStatus=ComplaintStatus.OPEN; Instant createdAt=Instant.now(); Instant updatedAt=Instant.now(); Instant dueAt; Instant resolvedAt; @Version long version; public UUID getId(){return id;} public User getResident(){return resident;} public void setResident(User x){resident=x;} public ComplaintCategory getCategory(){return category;} public void setCategory(ComplaintCategory x){category=x;} public String getTitle(){return title;} public void setTitle(String x){title=x;} public String getDescription(){return description;} public void setDescription(String x){description=x;} public Priority getPriority(){return priority;} public void setPriority(Priority x){priority=x;} public ComplaintStatus getCurrentStatus(){return currentStatus;} public void setCurrentStatus(ComplaintStatus x){currentStatus=x;updatedAt=Instant.now();} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public Instant getDueAt(){return dueAt;} public void setDueAt(Instant x){dueAt=x;} public Instant getResolvedAt(){return resolvedAt;} public void setResolvedAt(Instant x){resolvedAt=x;} }
